    public void handlePreScanCommand(String type, JsonObject jsonEntry) {
        if ("PRE_SCAN_CLEAR_GRID".equals(type)) {
            sendPreScanReset();
            return;
        }

        if ("PRE_SCAN_REFRESH_PAGE".equals(type)) {
            Thread worker = new Thread(
                    this::refreshPreScanPage,
                    "pre-scan-refresh-" + (selectedBotJob == null ? "unknown" : selectedBotJob.getId()));
            worker.setDaemon(true);
            worker.start();
            return;
        }

        if (!"PRE_SCAN_PAGE".equals(type)) {
            return;
        }

        String searchTerms = jsonEntry != null && jsonEntry.has("searchTerms")
                ? jsonEntry.get("searchTerms").getAsString()
                : "";
        boolean searchHidden = jsonEntry != null
                && jsonEntry.has("searchHiddenFields")
                && jsonEntry.get("searchHiddenFields").getAsBoolean();

        Thread worker = new Thread(
                () -> runPreScan(searchTerms, searchHidden),
                "pre-scan-" + (selectedBotJob == null ? "unknown" : selectedBotJob.getId()));
        worker.setDaemon(true);
        worker.start();
    }

    private void refreshPreScanPage() {
        if (selectedBotJob == null) {
            log.warn("PRE SCAN refresh skipped: no selected bot job");
            return;
        }

        String endpointUrl = selectedEndpointUrl();
        if (Strings.isNullOrEmpty(endpointUrl)) {
            log.warn("PRE SCAN refresh skipped: no endpoint URL selected");
            sendPreScanStatus("failed", "No endpoint URL selected.", 0);
            return;
        }

        String browserType = arPropertyManager.getProperty(ARPropertyEnum.BROWSER);
        String optionsConfig = preScanOptionsConfig();

        try {
            if (preScanDriver == null || !preScanDriver.isOpen()) {
                ensurePreScanBrowserOpen(browserType, endpointUrl, optionsConfig);
            } else {
                sendPreScanStatus("running", "Refreshing browser page...", 0);
                preScanDriver.reload();
            }
            sendPreScanStatus("done", "Web page refreshed. Run Page Scanner to update the grid.", 0);
        } catch (Exception error) {
            log.error("PRE SCAN refresh failed", error);
            sendPreScanStatus("failed", String.valueOf(error.getMessage()), 0);
        }
    }

    private void runPreScan(String searchTerms, boolean searchHidden) {
        if (selectedBotJob == null) {
            log.warn("PRE SCAN skipped: no selected bot job");
            return;
        }

        if (!preScanRunning.compareAndSet(false, true)) {
            log.warn("PRE SCAN skipped: a scan is already in progress");
            sendPreScanStatus("running", "A pre-scan is already in progress...", 0);
            return;
        }

        try {
            String endpointUrl = selectedEndpointUrl();
            if (Strings.isNullOrEmpty(endpointUrl)) {
                log.warn("PRE SCAN skipped: no endpoint URL selected");
                sendPreScanStatus("failed", "No endpoint URL selected.", 0);
                return;
            }

            sendPreScanStatus("waiting", "Starting pre-scan for " + endpointUrl, 0);
            sendPreScanReset();

            String browserType = arPropertyManager.getProperty(ARPropertyEnum.BROWSER);
            String optionsConfig = preScanOptionsConfig();

            ensurePreScanBrowserOpen(browserType, endpointUrl, optionsConfig);
            // Legacy parity: in AR Web Factory the page has been open (and hydrated) long
            // before the user clicks Page Scanner. Here the scan can fire right after
            // DOMContentLoaded, so wait until the network is quiet and the DOM stops
            // mutating — otherwise the first scan sees the half-rendered page.
            sendPreScanStatus("waiting", "Loading the Page - waiting to settle...", 0);
            long settledMs = preScanDriver.waitForPageSettled(15000);
            log.info("PRE SCAN - page settled after {} ms", settledMs);
            sendPreScanStatus("running", "web elements...", 0);
            List<ElementDTO> elements = preScanDriver.scanElements(searchTermsArray(searchTerms), searchHidden);
            elements = keepActionableElements(elements);
            resolvePreScanNames(elements);
            persistPreScanDiagnostics(elements);
            sendPreScanElements(elements);
            int count = elements == null ? 0 : elements.size();
            sendPreScanStatus(
                    count == 0 ? "empty" : "done",
                    count == 0 ? "No elements found." : "Found " + count + " web element(s).",
                    count);
            log.info("PRE SCAN - sent {} elements to preScannerGrid", elements == null ? 0 : elements.size());
        } catch (Exception error) {
            log.error("PRE SCAN failed", error);
            sendPreScanStatus("failed", String.valueOf(error.getMessage()), 0);
            Platform.runLater(() -> performMessage.errorMessage(
                    "PRE SCAN - Failed",
                    "<span style='color: #D32F2F; font-weight: bold;'>" + String.valueOf(error.getMessage())
                            + "</span>",
                    "The lightweight scanner could not complete for the selected URL.",
                    null,
                    null,
                    0));
        } finally {
            preScanRunning.set(false);
        }
    }

    /**
     * Every element the pre-scan ships must map to an executable action: input = the bot
     * can type, button = it can click, output/label = it can read. Anything else (bare
     * div/span containers matched by a broad selector) is noise for the dashboard and the
     * diagnostics dumps, so it is dropped here — pre-scan path only, legacy untouched.
     */
    private List<ElementDTO> keepActionableElements(List<ElementDTO> elements) {
        if (elements == null || elements.isEmpty()) {
            return elements;
        }
        List<ElementDTO> actionable = new ArrayList<>();
        for (ElementDTO element : elements) {
            String type = element == null
                    ? ""
                    : java.util.Objects.toString(element.getTypeElement(), "").toLowerCase(java.util.Locale.ROOT);
            if (type.equals("input") || type.equals("button") || type.equals("output") || type.equals("label")) {
                actionable.add(element);
            }
        }
        int dropped = elements.size() - actionable.size();
        if (dropped > 0) {
            log.info("PRE SCAN - dropped {} non-actionable element(s) (no type/click/read action)", dropped);
        }
        return actionable;
    }

    /**
     * Naming parity with the legacy Page Scanner: screenshot the pre-scan browser,
     * correlate the scanned element rects with the OCR words, and let
     * {@code ElementTextResolver} fill {@code definedName} / correct {@code someText} —
     * the same chain {@code PerformListElements} runs after a legacy scan. Mutates the
     * elements in place BEFORE they are dumped/sent, so both the dashboard and
     * {@code elementDTO-PS-BJ.json} carry resolved names. Failures are non-fatal: the
     * scan still ships, just with unresolved names.
     */
    private void resolvePreScanNames(List<ElementDTO> elements) {
        if (elements == null || elements.isEmpty()) {
            return;
        }
        try {
            sendPreScanStatus("running", "Resolving element names (OCR)...", elements.size());
            String jsonPath = arPropertyManager.getProperty(ARPropertyEnum.PATH_DB);
            Integer scanHomeBankingId = selectedBotJob.getHomeBankingId();
            Integer scanHomeUrlId = selectedBotJob.getHomeUrlId();
            ElementDTO[] asArray = elements.toArray(new ElementDTO[0]);

            com.allinweb.ch.util.PageDiagnosticDumper.dumpRectsFromElements(
                    preScanDriver, asArray, jsonPath, "page-BJ");
            com.allinweb.ch.util.PageOcrDumper.runAndDump(
                    preScanDriver, asArray, jsonPath, "page-BJ", scanHomeBankingId, scanHomeUrlId);

            // Keep the pre-OCR scanned text so the dashboard's per-block OCR review panel
            // can show scanned vs resolved and let the client agree/defer per element.
            String[] scannedTexts = new String[asArray.length];
            for (int i = 0; i < asArray.length; i++) {
                scannedTexts[i] = asArray[i] == null ? null : asArray[i].getSomeText();
            }

            com.allinweb.ch.model.OcrConfig resolverCfg =
                    com.allinweb.ch.facade.OcrConfigService.getInstance().resolveFor(scanHomeBankingId, scanHomeUrlId);
            // The correlation file name is fixed by PageOcrDumper regardless of prefix.
            com.allinweb.ch.facade.ElementTextResolver.resolveAll(
                    asArray,
                    java.nio.file.Paths.get(
                            jsonPath, com.allinweb.ch.util.PageDiagnosticDumper.SUBFOLDER, "ocr-correlation-HP.json"),
                    resolverCfg);

            for (int i = 0; i < asArray.length; i++) {
                ElementDTO element = asArray[i];
                String scanned = scannedTexts[i];
                if (element == null || Strings.isNullOrEmpty(scanned) || scanned.equals(element.getSomeText())) {
                    continue;
                }
                AttributeData[] existing =
                        element.getAttributeData() == null ? new AttributeData[0] : element.getAttributeData();
                AttributeData[] updated = new AttributeData[existing.length + 1];
                System.arraycopy(existing, 0, updated, 0, existing.length);
                updated[existing.length] = new AttributeData("scanned-text", scanned);
                element.setAttributeData(updated);
            }
        } catch (Exception ocrError) {
            log.warn("PRE SCAN - OCR name resolution failed (non-fatal): {}", ocrError.getMessage());
        }
    }

    /**
     * Comparison artifact for tracking differences against the original AR Web Factory
     * Page Scanner: writes the same dumps {@code PerformListElements} produces
     * ({@code elementDTO-PS.json} / {@code AI-ElementDTO-PS.json}) under the {@code -BJ}
     * suffix. Note: pre-scan skips the OCR {@code ElementTextResolver}, so
     * {@code definedName} is empty here by design — comparisons should ignore that field
     * until resolver parity lands.
     */
    private void persistPreScanDiagnostics(List<ElementDTO> elements) {
        if (elements == null || elements.isEmpty()) {
            return;
        }
        try {
            String jsonPath = arPropertyManager.getProperty(ARPropertyEnum.PATH_DB);
            ElementDTO[] asArray = elements.toArray(new ElementDTO[0]);

            List<String> excludeList = List.of("optional", "blockMarked", "editMode");
            performMessage.outputJsonElementDTO(asArray, excludeList, "elementDTO-PS-BJ", jsonPath);

            List<String> aiExcludeList = List.of(
                    "optional",
                    "blockMarked",
                    "editMode",
                    "id",
                    "attributeData",
                    "typeElement",
                    "customXPath",
                    "shadowRoot",
                    "nestedShadow",
                    "searchAttributeValue",
                    "attributeType",
                    "attributeValue");
            performMessage.outputJsonElementDTO(asArray, aiExcludeList, "AI-ElementDTO-PS-BJ", jsonPath);
        } catch (Exception jsonError) {
            log.warn("PRE SCAN - failed to persist element JSON: {}", jsonError.getMessage());
        }
    }

    private void ensurePreScanBrowserOpen(String browserType, String endpointUrl, String optionsConfig) {
        if (preScanDriver == null || !preScanDriver.isOpen()) {
            preScanDriver = new ARPlaywrightDriver();
            log.info("PRE SCAN - opening isolated visible Playwright at {}", endpointUrl);
            sendPreScanStatus("waiting", "Loading the Page - Opening isolated browser...", 0);
            preScanDriver.openOrNavigate(browserType, endpointUrl, optionsConfig, false);
            return;
        }

        String currentUrl = "";
        try {
            currentUrl = preScanDriver.currentUrl();
        } catch (Exception ignored) {
            // If currentUrl cannot be read, still try to scan the active page.
        }
        log.info("PRE SCAN - scanning current isolated browser page {}", currentUrl);
        sendPreScanStatus("waiting", "Loading the Page - Using current browser page...", 0);
    }

    /**
     * Pane-free row test (Test Click / Test Input) against the ISOLATED pre-scan browser.
     * The legacy path runs {@code ARScannedElementPane.testingActions} on the shared
     * driver; here the scanned page lives in {@code preScanDriver}, so the test must too.
     * Results stream to the dashboard status bar (done/failed) instead of a modal.
     */
    public void handlePreScanElementTest(SplitDTO splitDTO, String testType) {
        if (preScanDriver == null || !preScanDriver.isOpen()) {
            sendPreScanStatus("failed", "No pre-scan browser open. Run the Page Scanner first.", 0);
            return;
        }
        ElementDTO[] details = splitDTO == null ? null : splitDTO.getElementDetails();
        if (details == null || details.length == 0 || details[0] == null) {
            return;
        }
        ElementDTO elementDTO = details[0];
        Thread worker = new Thread(
                () -> runPreScanElementTest(elementDTO, testType),
                "pre-scan-test-" + (selectedBotJob == null ? "unknown" : selectedBotJob.getId()));
        worker.setDaemon(true);
        worker.start();
    }

    private void runPreScanElementTest(ElementDTO elementDTO, String testType) {
        boolean isClick = "TEST_CLICK_DTO".equals(testType);
        String actionLabel = isClick ? "Test Click" : "Test Input";
        // Same display chain the grids use: clientNamed > definedName > someText > tagName.
        String label = !Strings.isNullOrEmpty(elementDTO.getClientNamed())
                ? elementDTO.getClientNamed()
                : !Strings.isNullOrEmpty(elementDTO.getDefinedName())
                        ? elementDTO.getDefinedName()
                        : !Strings.isNullOrEmpty(elementDTO.getSomeText())
                                ? elementDTO.getSomeText()
                                : elementDTO.getTagName();
        try {
            InstructionLoad instruction = PreScanApplyService.getInstance().buildTestInstruction(elementDTO);
            if (instruction == null) {
                sendPreScanStatus("failed", actionLabel + " failed - cannot map element: " + label, 0);
                return;
            }

            sendPreScanStatus("running", actionLabel + " - " + label, 0);
            boolean passed;
            if (isClick) {
                passed = preScanDriver.click(instruction);
            } else {
                // The grid rides the test value in defaultValue ('abc'); keep that fallback.
                String value =
                        Strings.isNullOrEmpty(elementDTO.getDefaultValue()) ? "abc" : elementDTO.getDefaultValue();
                passed = preScanDriver.fill(instruction, new FieldData(instruction.getName(), value));
            }
            sendPreScanStatus(
                    passed ? "done" : "failed", actionLabel + (passed ? " passed - " : " failed - ") + label, 0);
            log.info("PRE SCAN {} {} for element '{}'", actionLabel, passed ? "passed" : "failed", label);
        } catch (Exception error) {
            log.error("PRE SCAN {} failed for '{}'", actionLabel, label, error);
            sendPreScanStatus("failed", actionLabel + " failed - " + error.getMessage(), 0);
        }
    }

    private String preScanOptionsConfig() {
        HomeBankingLoadDTO homeBanking = performLists.getHomeBankingById(selectedBotJob.getHomeBankingId());
        if (homeBanking == null) {
            homeBanking = selectedBotJob.getHomeBankingLoadDTO();
        }
        return homeBanking != null && homeBanking.getOptionsConfig() != null ? homeBanking.getOptionsConfig() : "";
    }

    private void sendPreScanStatus(String status, String message, int elementCount) {
        if (selectedBotJob == null) {
            return;
        }
        java.util.Map<String, Object> payload = new java.util.LinkedHashMap<>();
        payload.put("status", status);
        payload.put("message", message == null ? "" : message);
        payload.put("elementCount", elementCount);
        payload.put("botJobId", selectedBotJob.getId());
        payload.put("botJobName", selectedBotJob.getName());
        payload.put("homeBankingId", selectedBotJob.getHomeBankingId());
        webSocketSessionManager.sendMessageJson(
                selectedBotJob.getHomeBankingId(), "preScannerGrid", gson.toJson(payload), "preScanStatus");
    }

    private String selectedEndpointUrl() {
        if (!Strings.isNullOrEmpty(reactEnvironmentUrl)) {
            return reactEnvironmentUrl;
        }
        HomeUrlDTO homeUrl = selectedBotJob == null
                ? null
                : performLists.getHomeUrlByBankId(selectedBotJob.getHomeBankingId(), selectedBotJob.getHomeUrlId());
        if (homeUrl != null && !Strings.isNullOrEmpty(homeUrl.getUrl())) {
            return homeUrl.getUrl();
        }
        return selectedBotJob != null && selectedBotJob.getHomeBankingLoadDTO() != null
                ? selectedBotJob.getHomeBankingLoadDTO().getUrl()
                : "";
    }

    private String[] searchTermsArray(String searchTerms) {
        if (Strings.isNullOrEmpty(searchTerms)) {
            // Same default profile the AR Web Factory pane scans with. Empty terms
            // would fall through to the scanner's kitchen-sink DEFAULT_SELECTOR
            // (which ends in "span, div") and flood the grid with container junk.
            return new String[] {"input", "textarea", "button", "a", "select", "label"};
        }
        return java.util.Arrays.stream(searchTerms.split(","))
                .map(String::trim)
                .filter(term -> !term.isEmpty())
                .toArray(String[]::new);
    }

    private void sendPreScanReset() {
        sendPreScanPayload(List.of());
    }

    private void sendPreScanElements(List<ElementDTO> elements) {
        if (elements == null || elements.isEmpty()) {
            sendPreScanReset();
            return;
        }
        int chunkSize = 25;
        for (int i = 0; i < elements.size(); i += chunkSize) {
            sendPreScanPayload(elements.subList(i, Math.min(i + chunkSize, elements.size())));
        }
    }

    private void sendPreScanPayload(List<ElementDTO> elements) {
        SplitDTO payload = new SplitDTO();
        payload.setHomeBankingId(selectedBotJob.getHomeBankingId());
        payload.setBotJobId(selectedBotJob.getId());
        payload.setBotJobName(selectedBotJob.getName());
        payload.setType("SEARCH_TOOL");
        payload.setSessionId("preScannerGrid");
        payload.setOperationId("searchTerms");
        payload.setElementDetails(elements.toArray(new ElementDTO[0]));
        payload.setBlocks(preScanBlockOptions());
        webSocketSessionManager.sendMessageJson(
                selectedBotJob.getHomeBankingId(), "preScannerGrid", gson.toJson(payload), "searchTerms");
    }

    private List<java.util.Map<String, Object>> preScanBlockOptions() {
        if (performLists.getListBlock().isEmpty()) {
            ErrorMessage errorMessage =
                    performDataBase.loadBlocks(selectedBotJob.getId(), selectedBotJob.getName(), "block");
            if (errorMessage != null) {
                log.warn("PRE SCAN - could not load blocks: {}", errorMessage.getErrorMessage());
            }
        }
        return performLists.getListBlock().stream()
                .filter(block -> block != null && block.getId() != null)
                .filter(block ->
                        block.getBotJobId() == null || selectedBotJob.getId().equals(block.getBotJobId()))
                .sorted(java.util.Comparator.comparingInt(
                        block -> block.getBlockOrderNumber() == null ? Integer.MAX_VALUE : block.getBlockOrderNumber()))
                .map(block -> {
                    java.util.Map<String, Object> option = new java.util.LinkedHashMap<>();
                    option.put("blockId", block.getId());
                    option.put("blockOrderNumber", block.getBlockOrderNumber());
                    option.put("blockName", block.getName());
                    return option;
                })
                .toList();
    }

    public void createBatFile(String excelFilePath, String enginePath, String configPath) {
        String projectType = selectedBotJob.getPriority();

        projectType = projectType.replaceAll(" ", "_");

        String batFileName = "execute_" + projectType.toLowerCase() + "_" + selectedBotJob.getHomeBankingId()
                + "_Botjob_" + selectedBotJob.getId() + ".bat";

        String basePath = arPropertyManager.getProperty(ARPropertyEnum.PATH_DB);
        String batFilePath = basePath + File.separator + batFileName; // Corrected path

        String javaCommand = "java.exe -jar \"" + enginePath + "\" execute/j "
                + selectedBotJob.getHomeBankingId() + " " + selectedBotJob.getId() + " " + 1 + " \"" + excelFilePath
                + "\" -c \""
                + configPath + "\"";

        try (FileWriter writer = new FileWriter(batFilePath)) {
            writer.write(javaCommand);

            performMessage.showCustomModalDialogDragWin11(
                    "BAT File Creation",
                    "<span style='color: #00695C; font-weight: bold; font-size: 1.1em;'>BAT file created at:</span>",
                    "<span style='color: #2E7D32; font-weight: bold;'></span> <span style='font-weight: bold;'>"
                            + basePath + "</span>", // changed color
                    "<span style='color: #00695C; font-weight: bold; font-size: 1.1em;'>BAT file name:</span>",
                    "<span style='color: #2E7D32; font-weight: bold;'></span> <span style='font-weight: bold;'>"
                            + batFileName + "</span>", // changed color
                    false,
                    "OK",
                    null,
                    0);

            log.info("BAT file created at: " + batFilePath);
        } catch (IOException error) {
            log.error("Error creating BAT file: " + error.getMessage());
            performMessage.errorMessage(
                    "BAT File Creation Error",
                    "<span style='color: #D32F2F; font-weight: bold; font-size: 1.1em;'>Failed to create file:</span>",
                    "<span style='font-weight: bold;'>" + batFilePath + "</span>.", // Filename on a new line
                    "<span style='color: #E65100; font-weight: bold;'>Please verify the application has the necessary write permissions for the directory.</span>",
                    "<span style='font-style: italic;'>Details: " + error.getMessage() + "</span>",
                    0);
        }
    }

    private void callScannerTool() {
        if (arPropertyManager.missingMandatoryPats()) {
            return;
        }

        if (!isScannerButtonClicked) { // Check if the button action was not already triggered
            isScannerButtonClicked = true; // Set the flag to prevent further clicks

            log.info("Calling openScannerButton");

            String threadName = "botJob-" + selectedBotJob.getId();
            arScene.startNewThread(threadName, () -> {
                executeScannerTask();
                isScannerButtonClicked = false; // Reset the flag after task completes
            });
        }
    }

    // Method where you start the thread (e.g., in a button's event handler)
    private void handleStartScanner() {
        String threadName = "botJob-" + selectedBotJob.getId(); // Use the ID for the thread name
        arScene.startNewThread(threadName, () -> {
            executeScannerTask();
            Platform.runLater(() -> {
                // Update UI here, if needed
                log.info("Scanner task completed for " + threadName);
            });
        });
    }

    public HomeUrlDTO findMatchingHomeUrlDTO(BotJobLoadDTO botJobLoadDTO) {
        Integer targetHomeUrlId = botJobLoadDTO.getHomeUrlId();
        HomeBankingLoadDTO homeBanking = botJobLoadDTO.getHomeBankingLoadDTO();

        if (homeBanking != null && homeBanking.getHomeUrlDTOs() != null) {
            return homeBanking.getHomeUrlDTOs().stream()
                    .filter(dto -> dto.getId().equals(targetHomeUrlId))
                    .findFirst()
                    .orElse(null);
        }

        return null;
    }

    private void executeScannerTask() {

        ErrorMessage errorMessage = performDBEngine.loadHomeBanking(selectedBotJob.getHomeBankingId());
        if (errorMessage == null) {
            errorMessage = performDBEngine.loadHomeUrls(selectedBotJob.getHomeBankingId());
        }

        if (errorMessage != null) {
            performMessage.errorMessageOperationFailed(errorMessage);
        }
        HomeBankingLoadDTO homeBanking = performLists.getListHomeBanking().isEmpty()
                ? null
                : performLists.getListHomeBanking().get(0);

        HomeUrlDTO homeUrlDTO = findMatchingHomeUrlDTO(selectedBotJob);
        if (homeUrlDTO != null) {
            selectedBotJob.setHomeUrlId(homeUrlDTO.getId());
            homeBanking.setUrl(homeUrlDTO.getUrl());
        }

        if (selectedBotJob.getBlockLoadDTOList() != null
                && !selectedBotJob.getBlockLoadDTOList().isEmpty()) {
            this.blockLoad = selectedBotJob.getBlockLoadDTOList().get(0);
        } else {

            errorMessage = performDataBase.loadBlocks(selectedBotJob.getId(), selectedBotJob.getName(), "block");
            if (errorMessage != null) {
                performMessage.errorMessageOperationFailed(errorMessage);
            }
            if (!performLists.getListBlock().isEmpty()) {
                this.blockLoad = performLists.getListBlock().get(0);
            }
        }

        try {
            arScannedElementScene.initialize(homeBanking, selectedBotJob, this.blockLoad);
            arScannedElementScene.showModal(); // Make sure the scene is shown
        } catch (Exception ex) {
            handleExceptionScan(ex);
        }
    }

    private void handleExceptionScan(Exception error) {
        // Log the exception

        if (error.getMessage().contains("null")) {
            log.error("Error: " + error.getMessage());
            return;
        }

        log.error("ERROR Calling openScannerButton -> Cause: " + error.getMessage());

        // Display the error message to the user
        String browser = arPropertyManager.getProperty(ARPropertyEnum.BROWSER);
        String webDriverPath = arPropertyManager.getProperty(ARPropertyEnum.PATH_WEBDRIVER);

        if (error.getMessage().contains("no such window: target window already closed")
                || error.getMessage().contains("web view not found")) {
            log.error("Error Calling SCANNER: {}", webDriverPath);
            performMessage.errorMessage(
                    "Error Calling SCANNER",
                    "<span style='font-style: italic;'>Web Browser was closed before the Scanner Tool!</span>",
                    "<span style='color: #E65100; font-weight: bold;'>WebDriver path:</span> <span style='font-weight: bold;'>"
                            + webDriverPath + "</span>",
                    "<span style='font-style: italic;'>Please close and Re-Open the Scanner Tool.</span>",
                    "<span style='font-style: italic;'>Details: " + "Web Browser was closed before the Scanner Tool"
                            + "</span>",
                    0);
        } else {

            //            "invalid session id"

            if (!error.getMessage().contains("Current browser version")) {
                log.error("Error Open URL: " + error.getMessage());

                //                performMessage.errorMessage("Error Open URL", msg1, msg2, msg3, msg4, 0);

                if (error.getMessage().contains("session deleted as the browser has closed the connection")
                        || error.getMessage().contains("Expected condition failed: waiting for com")) {
                    log.error("Interruption Calling SCANNER: {}", webDriverPath);
                    performMessage.errorMessage(
                            "Interruption Calling SCANNER",
                            "<span style='font-style: italic;'>Session deleted as the browser has closed the connection!</span>",
                            "<span style='color: #E65100; font-weight: bold;'>WebDriver path:</span> <span style='font-weight: bold;'>"
                                    + webDriverPath + "</span>",
                            "<span style='font-style: italic;'>Please close and Re-Open the Scanner Tool.</span>",
                            "<span style='font-style: italic;'>Details: "
                                    + "Web Browser was closed before the Scanner Tool" + "</span>",
                            0);
                } else {
                    log.error("WebDriver Access Issue: Browser: {} - {}", browser, webDriverPath);
                    performMessage.errorMessage(
                            "WebDriver Access Issue",
                            "<span style='color: #D32F2F; font-weight: bold; font-size: 1.1em;'>Failed to access WebDriver.</span>",
                            //                        "<span style='font-style: italic;'>It appears the WebDriver data
                            // directory might be locked by another process.</span>",
                            "<span style='font-weight: bold;'>Please ensure the following:</span>",
                            "<ul>" + "   <li>No other instances of the browser or WebDriver are currently running.</li>"
                                    + "   <li>The specified WebDriver path is correct and accessible: <span style='font-weight: bold;'>"
                                    + webDriverPath + "</span></li>"
                                    + "   <li>The configured browser is: <span style='font-weight: bold;'>"
                                    + browser + "</span></li>" + "</ul>",
                            "<span style='font-style: italic;'>If the issue persists, try closing all related browser processes and restarting the application.</span>",
                            0);
                }
            } else {
                log.error("Error Open URL: " + error.getMessage());

                int lastSlashIndex = webDriverPath.lastIndexOf('\\');
                String directoryPath = webDriverPath.substring(0, lastSlashIndex + 1); // includes the last backslash
                String fileName = webDriverPath.substring(lastSlashIndex + 1);

                log.error("Invalid URL or Navigation Error: {} - {} - {}", browser, directoryPath, fileName);
                performMessage.errorMessage(
                        "Invalid URL or Navigation Error",
                        "<span style='color: #D32F2F; font-weight: bold; font-size: 1.1em;'>The provided URL is invalid or cannot be reached.</span>",
                        "<span style='font-weight: bold;'>Please verify the following:</span>",
                        "<ul>"
                                + "   <li>The entered URL is valid and accessible.</li>"
                                + "   <li>The installed browser version: <span style='color: #008b8b; font-weight: bold;'>"
                                + browser + "</span></li>"
                                + "   <li>The WebDriver path:<br><span style='color: #008b8b; font-weight: bold;'>"
                                + directoryPath + "</span></li>"
                                + "   <li>The WebDriver file:<br><span style='color: #008b8b; font-weight: bold;'>"
                                + fileName + "</span></li>"
                                + "   <li>Ensure the WebDriver and browser are compatible and correctly configured.</li>"
                                + "</ul>",
                        "<span style='font-style: italic;'>Check the URL format (e.g., including https://) and review browser/WebDriver logs for more details.</span>",
                        0);
            }
        }

        //        Platform.runLater(() -> {
        //            JOptionPane.showMessageDialog(
        //                    null,
        //                    "An error has occurred Calling SCAN: Cause: " + ex.getMessage(),
        //                    "Error calling in SCAN",
        //                    JOptionPane.ERROR_MESSAGE);
        //        });
    }

